// JournalEntryWrite PATCH accepts any subset of the fields. An Entry is text, or at least one
// Attachment, or both (SPEC-12): a create or patch whose result has neither
// is 422 `journal/invalid-body` — a Location alone does not make an Entry.
// `asset_ids`, when present, replaces the whole list and is validated as a
// whole — a duplicate, an eleventh element, or any id that is not a ready
// image Asset owned by the caller is 422 `journal/invalid-asset` with
// `detail` naming the id and the reason, and nothing is stored. `location`
// sets the Location when it is an object, clears it when null, and keeps
// it when absent; a violation of its rules is 422 `journal/invalid-location`.
// `mood` follows the same three states: a string sets, `null` clears,
// absent keeps.
type JournalEntryWrite struct {
	// AssetIds The Entry's Attachments in display order — image Assets owned by the caller with status `ready`. Replaces the whole list when present.
	AssetIds *[]openapi_types.UUID `json:"asset_ids,omitempty"`

	// BodyMd Plain markdown. Absent or empty is allowed only when the resulting Entry has at least one Attachment.
	BodyMd *string `json:"body_md,omitempty"`

	// Location An object sets the Location, `null` clears it, absent keeps it.
	Location *JournalLocation `json:"location,omitempty"`

	// Mood A string sets the mood (1–80 characters after trimming), `null` clears it, absent keeps it (SPEC-12 T5).
	Mood *string `json:"mood,omitempty"`

	// OccurredAt Optional; defaults to now. Backdating and future-dating are allowed.
	OccurredAt *time.Time `json:"occurred_at,omitempty"`
}

// JournalLocation Where an Entry happened (SPEC-12 T3) — a property of the Entry, not an
// Attachment. All three fields together or the whole thing null: a
// name-only or coordinates-only Location is 422 `journal/invalid-location`.
// Coordinates are kept to four decimal places.
